use blit_core::{
    generated::{FilterSpec, TransferOperationSpec},
    mirror_planner::MirrorPlanner,
    remote::transfer::operation_spec::{NormalizedTransferOperation, SUPPORTED_SPEC_VERSION},
    transfer_session::CONTRACT_VERSION,
    transfers::filter::{build, build_spec, FilterInputs},
};
use std::{collections::HashSet, path::Path};

fn peer_filter(wire: FilterSpec) -> blit_core::fs_enum::FileFilter {
    NormalizedTransferOperation::from_spec(TransferOperationSpec {
        spec_version: SUPPORTED_SPEC_VERSION,
        filter: Some(wire),
        ..Default::default()
    }).unwrap().filter.unwrap()
}

#[test]
fn local_and_wire() {
    for pattern in [r"{a\,**/x,b}", r"{a\{**/x,b}", r"**\/x", r"reports/\*.txt"] {
        for ignore_case in [false,true] {
            let patterns = [pattern.to_string()];
            let inputs = FilterInputs {
                include: &patterns, exclude: &[], files_from: None, retry_only: None,
                retry_only_raw: None, source_root: None, ignore_case, min_size: None,
                max_size: None, min_age: None, max_age: None, resolved: None,
            };
            let local = build(&inputs).unwrap();
            let wire = build_spec(&inputs).unwrap();
            let wire_text = wire.include.clone();
            let peer = peer_filter(wire);
            for name in ["a/x","a/foo/x","a,/x","a,z/x","a{/x","b","reports/*.txt"] {
                let p = Path::new(name);
                let left = local.allows_entry(Some(p), p, 1, None);
                let right = peer.allows_entry(Some(p), p, 1, None);
                if left != right {
                    println!("DIVERGE ignore_case={ignore_case} typed={pattern} wire={} name={name} local={left} peer={right}", wire_text[0]);
                }
            }
        }
    }
}

#[test]
fn received_list_scope() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::create_dir(dir.path().join("destination-only")).unwrap();
    std::fs::write(dir.path().join("unlisted.txt"), b"data").unwrap();
    let filter = peer_filter(FilterSpec { files_from_set: true, ..Default::default() });
    let plan = MirrorPlanner::new(false)
        .plan_session_deletions(dir.path(), &HashSet::new(), &[], &HashSet::new(), true, &filter).unwrap();
    println!("LIST contract={CONTRACT_VERSION} spec={SUPPORTED_SPEC_VERSION} delete_dirs={:?} delete_files={:?}", plan.dirs, plan.files);
}
