from pathlib import Path
from subprocess import Popen, PIPE
import os, sys, tarfile
repo=Path(sys.argv[1])
head="a13238b6e7492be8b173899978efb633f3d7d151"
checked=0
with Popen(["git","-C",str(repo),"archive",head,"--","Cargo.toml","Cargo.lock","crates"],stdout=PIPE) as proc:
    with tarfile.open(fileobj=proc.stdout,mode="r|") as src:
        for f in src:
            if f.isfile():
                if Path(f.name).read_bytes() != src.extractfile(f).read():
                    raise SystemExit(f"export differs at {f.name}")
                checked+=1
            elif f.issym() and os.readlink(f.name)!=f.linkname:
                raise SystemExit(f"link differs at {f.name}")
    if proc.wait():
        raise SystemExit("archive failed")
assert not Path("crates/blit-core/tests/review_reader_comparison.rs").exists()
print("verified all",checked,"exported workspace files against pinned head")
